def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 7:
                objects.setdefault(grid[r][c], []).append((r, c))

    def box(cells):
        return (min(r for r, c in cells), max(r for r, c in cells),
                min(c for r, c in cells), max(c for r, c in cells))

    def square_score(item):
        cells = item[1]
        top, bottom, left, right = box(cells)
        if bottom-top != right-left:
            return -1
        return sum(r in (top, bottom) or c in (left, right)
                   for r, c in cells) / len(cells)

    color, cells = max(objects.items(), key=square_score)
    top, bottom, left, right = box(cells)
    size = bottom-top+1
    out = [[7]*w for _ in range(h)]
    # Draw inward from the corner occupied by the square.
    downward = top+size//2 < h/2
    rightward = left+size//2 < w/2
    r = top if downward else bottom
    c = left if rightward else right
    dr = 1 if downward else -1
    dc = 1 if rightward else -1
    for _ in range(size):
        out[r][c] = color
        r += dr
        c += dc
    return out
